        if (cosine >= sd_config.minimum_cosine) {
            // Accept: Blend reference
            // ref_new = (1-alpha)*ref_old + alpha*sample
            adcs_vec3_t term1 = adcs_vec3_scale(&sd_state.reference, 1.0 - sd_config.alpha);
            adcs_vec3_t term2 = adcs_vec3_scale(&normalized_sample, sd_config.alpha);
            sd_state.reference = adcs_vec3_add(&term1, &term2);

            sd_state.rejects = 0;
            sd_state.mode = SD_TRACK;
            sd_state.initialized = 1;

            sd_output.mode = SD_TRACK;
            sd_output.accepted = 1;
            sd_output.rejects = 0;
            sd_output.cosine = cosine;
            sd_output.innovation_rad = acos(cosine);
            sd_output.reference = sd_state.reference;
        } else {
            // Reject
            sd_state.rejects++;
            if (sd_state.rejects >= sd_config.max_rejects) {
                sd_state.mode = SD_LOST;
            } else {
                sd_state.mode = SD_REJECT;
            }

            sd_output.mode = sd_state.mode;
            sd_output.accepted = 0;
            sd_output.rejects = sd_state.rejects;
            sd_output.cosine = cosine;
            sd_output.innovation_rad = acos(cosine);
            sd_output.reference = sd_state.reference;
        }
        break;
    }
    case SD_LOST: {
        // Reference is frozen. Test against reacquire threshold.
        cosine = adcs_vec3_dot(&sd_state.reference, &normalized_sample);

        if (cosine >= sd_config.reacquire_min_cosine) {
            sd_state.reacquire_count++;
            if (sd_state.reacquire_count >= sd_config.reacquire_confirm) {
                // Reacquisition successful: Blend and return to TRACK
                adcs_vec3_t term1 = adcs_vec3_scale(&sd_state.reference, 1.0 - sd_config.alpha);
                adcs_vec3_t term2 = adcs_vec3_scale(&normalized_sample, sd_config.alpha);
                sd_state.reference = adcs_vec3_add(&term1, &term2);

                sd_state.rejects = 0;
                sd_state.reacquire_count = 0;
                sd_state.mode = SD_TRACK;
                sd_state.initialized = 1;

                sd_output.mode = SD_TRACK;
                sd_output.accepted = 1;
                sd_output.rejects = 0;
                sd_output.cosine = cosine;
                sd_output.innovation_rad = acos(cosine);
                sd_output.reference = sd_state.reference;
            } else {
                // Still in LOST, incrementing count
                sd_output.mode = SD_LOST;
                sd_output.accepted = 0;
                sd_output.rejects = sd_state.rejects;
                sd_output.cosine = cosine;
                sd_output.innovation_rad = acos(cosine);
                sd_output.reference = sd_state.reference;
            }
        } else {
            // Below threshold: Reset count, stay LOST
            sd_state.reacquire_count = 0;

            sd_output.mode = SD_LOST;
            sd_output.accepted = 0;
            sd_output.rejects = sd_state.rejects;
            sd_output.cosine = cosine;
            sd_output.innovation_rad = acos(cosine);
            sd_output.reference = sd_state.reference;
        }
        break;
    }
    case SD_FAULT: {
        // Stay latched
        sd_output.mode = SD_FAULT;
        sd_output.accepted = 0;
        sd_output.rejects = sd_state.rejects;
        sd_output.cosine = 0.0;
        sd_output.innovation_rad = 0.0;
        sd_output.reference = sd_state.reference;
        break;
    }
    default: {
        // Initial state or OFF (from disable). First valid sample initializes it.
        sd_state.initialized = 1;
        sd_state.reference = normalized_sample;
        sd_state.rejects = 0;
        sd_state.mode = SD_TRACK;
        sd_state.reacquire_count = 0;

        sd_output.mode = SD_TRACK;
        sd_output.accepted = 1;
        sd_output.rejects = 0;
        sd_output.cosine = 1.0; // Perfect match with itself
        sd_output.innovation_rad = 0.0;
        sd_output.reference = sd_state.reference;
        break;
    }
}
